  for (let k = 0; k < NF; k++){ const u = 1 - 2*k/NF; P.push([a*u, b + bul*(1 - u*u)]); }              // south face
  for (let k = 0; k < NE; k++){ const v = 1 - 2*k/NE; P.push([-a - eb*(1 - v*v), b*v]); }              // west end
