    const bay = [[-29.5, 20.6], [29.5, 20.6], [21.4, 24.6], [12.8, 27.9], [8.2, 29.1], [-0.2, 30.0], [-9.0, 29.1], [-13.2, 28.0], [-18.0, 26.2]];
