      // drum crown: a lit ring, the step in to the inner drum, the inner drum to 325 m, the needle hub, the spire to 384 m
      cylw(B, TOPC, x, z, R + 0.4, R + 0.4, HD - 3.2, HD + 0.6, 28, null);
