    for (let k = 0; k < 4; k++){ const a = k/4*TAU + PI/4; obox(B, '#8f9290', Math.cos(a)*12.6, Math.sin(a)*12.6, 1, 0, 0.3, 0.3, HS + 15.2, 160); redLight(B, Math.cos(a)*12.6, 160, Math.sin(a)*12.6, 0.3); }
    // base
